 const markerGeometry=new THREE.RingGeometry(.22,.28,32),markerMaterial=new THREE.MeshBasicMaterial({color:'#f2e0ad',transparent:true,opacity:.9,depthWrite:false,side:THREE.DoubleSide}),marker=new THREE.Mesh(markerGeometry,markerMaterial);marker.rotation.x=-Math.PI/2;marker.visible=false;world.scene.add(marker);let markerUntil=0;
 function tap(x,y){if(paused||!ready)return;const rect=canvas.getBoundingClientRect();ndc.set((x-rect.left)/rect.width*2-1,1-(y-rect.top)/rect.height*2);raycaster.setFromCamera(ndc,camera);const hit=world.pick(raycaster);if(!hit)return;if(hit.id){select(hit.id);return;}el('world-intro').hidden=true;entered=true;el('place-card').hidden=true;rideUntil=0;if(state.walkTo(hit.point)){const goal=state.walker.path[state.walker.path.length-1];marker.position.set(goal.x,walkingHeight(goal.x,goal.z)+.07,goal.z);marker.visible=true;markerUntil=state.time+3;el('world-hint').textContent='和你一起，慢慢走到那里。';navigator.vibrate?.(5);}else toast('那里没有能走的小径。试着走近木桥或草坡。');}
