 listen(canvas,'pointerdown',event=>{if(paused||!ready||event.button>2)return;event.preventDefault();cancelRide();pointers.set(event.pointerId,{x:event.clientX,y:event.clientY,sx:event.clientX,sy:event.clientY,moved:false,pan:event.button===2||event.shiftKey});if(pointers.size>1)for(const p of pointers.values())p.moved=true;canvas.setPointerCapture?.(event.pointerId);});
