 listen(el('world-enter'),'click',()=>{if(failures.length){location.reload();return;}entered=true;el('world-intro').hidden=true;canvas.focus({preventScroll:true});save();toast('点点草地，带她们散步；也可以去听钟声，或坐一程缆车。',5);});
