 document.querySelectorAll('[data-weather]').forEach(button=>listen(button,'click',()=>{state.setWeather(button.dataset.weather);sync();save();navigator.vibrate?.(8);}));document.querySelectorAll('[data-day]').forEach(button=>listen(button,'click',()=>{state.setDay(button.dataset.day);sync();save();}));listen(el('time-flow'),'click',()=>{state.auto=!state.auto;if(reduced.matches&&state.auto){state.auto=false;toast('已按系统偏好保留静态光线，可以手动选清晨、正午或傍晚。');}sync();save();});
 document.querySelectorAll('[data-view]').forEach(button=>listen(button,'click',()=>{cancelRide();const views={overview:[0,5,-5,1,.58,.66],village:[0,4,-4,1.9,.48,.64],meadow:[4,1,13,1.7,.55,.82]},v=views[button.dataset.view];rig.desired.set(v[0],v[1],v[2]);rig.targetZoom=v[3];rig.targetYaw=v[4];rig.targetPitch=v[5];document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));el('place-card').hidden=true;save();}));
 listen(el('zoom-in'),'click',()=>rig.targetZoom=clamp(rig.targetZoom*1.2,.65,2.8));listen(el('zoom-out'),'click',()=>rig.targetZoom=clamp(rig.targetZoom/1.2,.65,2.8));listen(el('world-pause'),'click',pause);listen(el('world-help'),'click',pause);listen(el('world-resume'),'click',resume);listen(el('world-menu'),'cancel',event=>{event.preventDefault();resume();});
 listen(el('sound-toggle'),'click',async()=>{sound=!sound;if(sound&&!await unlockSound())sound=false;el('sound-toggle').setAttribute('aria-pressed',String(sound));el('sound-toggle').querySelector('span').textContent=sound?'开':'关';if(sound)cue(660,.35,.01);else audio?.suspend();});
